INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HSD13-002', 'NORMAL', 'Boat Goes Binted', '[ターンに1回]相手のセンターポジションとコラボポジションのホロメンを入れ替える。', 1, '{"type": "MOVE_ZONE", "target": "ENEMY_CENTER", "rawText": "[ターンに1回]相手のセンターポジションとコラボポジションのホロメンを入れ替える。"}'::jsonb);
INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HSD13-002', 'SP', '自由奔放な『追跡者』', '[ゲームに1回]自分のデッキから、2ndホロメンの〈ジジ・ムリン〉2枚を公開し、ステージに出す。そしてデッキをシャッフルする。その後、自分のアーカイブのエールを自分のホロメン全員に1枚ずつ送る。', 3, '{"type": "SEARCH", "target": "SELF", "rawText": "[ゲームに1回]自分のデッキから、2ndホロメンの〈ジジ・ムリン〉2枚を公開し、ステージに出す。そしてデッキをシャッフルする。その後、自分のアーカイブのエールを自分のホロメン全員に1枚ずつ送る。"}'::jsonb);
