INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD12-015', FALSE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "脱獄を果たした共犯者たち\nhSD12-015\n脱獄を果たした共犯者たち\nカードタイプ\nサポート・イベント\nレアリティ\nU\n収録商品\nスタートデッキ 推し Advent \n能力テキスト\nこのカードは、自分のステージのホロメン全員が#Adventを持つホロメンでなければ使えない。\n相手のセンターホロメンに特殊ダメージ20を与える。その後、自分のアーカイブのエール1枚を自分のホロメンに送る。\n自分の〈脱獄を果たした共犯者たち〉はターンに1回しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
INSERT INTO cards (card_id, name, rarity, image_url, card_type, expansion_code, card_no, tags_json, source_url) VALUES ('HSD12-016', 'GEOW', 'C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD12/hSD12-016_C.png', 'SUPPORT', 'HSD12', 'HSD12-016', '[]'::jsonb, 'https://hololive-official-cardgame.com/cardlist/?id=1765&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text') ON CONFLICT (card_id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, image_url = EXCLUDED.image_url, card_type = EXCLUDED.card_type, expansion_code = EXCLUDED.expansion_code, card_no = EXCLUDED.card_no, tags_json = EXCLUDED.tags_json, source_url = EXCLUDED.source_url, updated_at = CURRENT_TIMESTAMP;
INSERT INTO card_variants (card_id, variant_code, variant_name, image_url, source_url, is_default) VALUES ('HSD12-016', 'DEFAULT', '預設圖', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD12/hSD12-016_C.png', 'https://hololive-official-cardgame.com/cardlist/?id=1765&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text', TRUE) ON CONFLICT (card_id, variant_code) DO UPDATE SET variant_name = EXCLUDED.variant_name, image_url = EXCLUDED.image_url, source_url = EXCLUDED.source_url, is_default = EXCLUDED.is_default, updated_at = CURRENT_TIMESTAMP;
INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD12-016', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "GEOW\nhSD12-016\nGEOW\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nスタートデッキ 推し Advent \n能力テキスト\nこのマスコットが付いているホロメンのHP+20。\nこのマスコットを手札から1st以上の〈古石ビジュー〉に付けた時、自分のステージのエール1枚をアーカイブできる：自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
