INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-094', TRUE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "ワークアウト\nhBP06-094\nワークアウト\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nC\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\nこのカードは、自分のコラボホロメンがいるか、相手のコラボホロメンがいない時にしか使えない。\nこのターンの間、自分のステージのホロメン1人のアーツ+20。そのホロメンがBuzzホロメンか2ndホロメンなら、かわりに、そのホロメンのアーツ+50。\nLIMITED：ターンに1枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
INSERT INTO cards (card_id, name, rarity, image_url, card_type, expansion_code, card_no, tags_json, source_url) VALUES ('HBP06-095', 'IDENTIFY -AREA 15-', 'U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP06/hBP06-095_U.png', 'SUPPORT', 'HBP06', 'HBP06-095', '[]'::jsonb, 'https://hololive-official-cardgame.com/cardlist/?id=1572&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text') ON CONFLICT (card_id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, image_url = EXCLUDED.image_url, card_type = EXCLUDED.card_type, expansion_code = EXCLUDED.expansion_code, card_no = EXCLUDED.card_no, tags_json = EXCLUDED.tags_json, source_url = EXCLUDED.source_url, updated_at = CURRENT_TIMESTAMP;
INSERT INTO card_variants (card_id, variant_code, variant_name, image_url, source_url, is_default) VALUES ('HBP06-095', 'DEFAULT', '預設圖', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP06/hBP06-095_U.png', 'https://hololive-official-cardgame.com/cardlist/?id=1572&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text', TRUE) ON CONFLICT (card_id, variant_code) DO UPDATE SET variant_name = EXCLUDED.variant_name, image_url = EXCLUDED.image_url, source_url = EXCLUDED.source_url, is_default = EXCLUDED.is_default, updated_at = CURRENT_TIMESTAMP;
INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-095', TRUE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "IDENTIFY -AREA 15-\nhBP06-095\nIDENTIFY -AREA 15-\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\nこのカードは、自分のステージのホロメン全員が#ID1期生を持つホロメンでなければ使えない。\n自分のデッキから、#ID1期生を持つホロメン2枚を公開し、手札に加える。そしてデッキをシャッフルする。その後、自分のエールデッキの枚数が0枚なら、このターンの間、自分の#ID1期生を持つホロメンが相手のセンターホロメンをダウンさせた時、相手のライフ-1。\nLIMITED：ターンに1枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
