INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-097', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "カワイイスタジャン\nhBP06-097\nカワイイスタジャン\nカードタイプ\nサポート・ツール\nレアリティ\nC\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\n◆Buzzホロメンに付いていたら能力追加\n■このツールが付いているホロメンのHP+30。\n■相手のメインステップの間、このツールが付いているホロメンのHPは相手の能力で減らず、変動しない。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
