INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-098', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "鬼神刀「阿修羅」\nhBP06-098\n鬼神刀「阿修羅」\nカードタイプ\nサポート・ツール\nレアリティ\nU\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆〈百鬼あやめ〉に付いていたら能力追加\nこのツールが付いているホロメンがコラボした時、自分のライフが1で、相手のコラボホロメンがいないなら、相手は、自身のバックホロメン1人をコラボポジションに移動させる（移動はコラボとしては扱わない）。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
