INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-102', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "えびふらいおん\nhBP06-102\nえびふらいおん\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\nこのマスコットが付いているホロメンのHP+20。\n◆〈夏色まつり〉に付いていたら能力追加\n相手のターンで、このマスコットが付いているホロメンがダウンした時、このホロメンの黄エール1枚を自分の他の〈夏色まつり〉に付け替えられる。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
