INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-103', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "まつりす\nhBP06-103\nまつりす\nカードタイプ\nサポート・ファン\nレアリティ\nC\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\n自分の[推しホロメンか#1期生を持つホロメン]の能力でサイコロを振った時、このファンをアーカイブできる：そのサイコロの目の数1つを4として扱う。\nこのファンは、自分の〈夏色まつり〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
