INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP06-104', FALSE, NULL, NULL, 'ADD_CHEER', '{"type": "ADD_CHEER", "rawText": "スバ友\nhBP06-104\nスバ友\nカードタイプ\nサポート・ファン\nレアリティ\nC\n収録商品\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\n相手のターンで、このファンが付いているホロメンがダウンした時、自分のエールデッキの上から1枚を自分の〈大空スバル〉に送れる。\nこのファンは、自分の〈大空スバル〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
