INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HSD10-004', 'パワフルな運転手だよ！ 50', '自分のステージに#FLOW GLOWを持つホロメンが3人以上いるなら、自分のエールデッキの上から1枚を自分のバックホロメンに送れる。', '{"GREEN": 1, "COLORLESS": 1}'::jsonb, '{"type": "DAMAGE", "target": "SELF", "rawHeader": "緑◇パワフルな運転手だよ！ 50", "rawEffect": "自分のステージに#FLOW GLOWを持つホロメンが3人以上いるなら、自分のエールデッキの上から1枚を自分のバックホロメンに送れる。"}'::jsonb, 0);
