INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-075', FALSE, NULL, NULL, 'HEAL', '{"type": "HEAL", "rawText": "牛丼\nhBP05-075\n牛丼\nカードタイプ\nサポート・イベント\nタグ\n#食べ物\nレアリティ\nC\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\n自分のホロメン1人を選ぶ。このターンの間、選んだホロメンのバトンタッチに必要な無色エール-2。その後、選んだホロメンのHP20回復。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
