INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-076', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "ちょこのビーフストロガノフ\nhBP05-076\nちょこのビーフストロガノフ\nカードタイプ\nサポート・イベント\nタグ\n#食べ物\nレアリティ\nU\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\nこのターンの間、自分のステージのホロメン1人のアーツ+10。その後、このターンの間、自分のステージの2ndホロメンの〈癒月ちょこ〉1人のアーツ+10。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
