INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-077', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "バカタレサーカス\nhBP05-077\nバカタレサーカス\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\nこのカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n自分のデッキの上から4枚を見る。その中から、〈白上フブキ〉と〈不知火フレア〉と〈角巻わため〉と〈尾丸ポルカ〉を好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
