INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-081', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "白銀ノエルのメイス\nhBP05-081\n白銀ノエルのメイス\nカードタイプ\nサポート・ツール\nレアリティ\nU\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆1st以上の〈白銀ノエル〉に付いていたら能力追加\nこのツールが付いているホロメンにエールが3枚以上付いている間、このホロメンのアーツ+20。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
