INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-082', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "アキ・ローゼンタールの斧\nhBP05-082\nアキ・ローゼンタールの斧\nカードタイプ\nサポート・ツール\nレアリティ\nU\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\nこのカードは、自分の手札1枚か自分のステージの〈石の斧〉1枚をアーカイブしなければ使えない。\nこのツールが付いているホロメンのアーツ+10。\n◆2nd以上の〈アキ・ローゼンタール〉に付いていたら能力追加\nこのツールが付いているホロメンのアーツ+40。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
