INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP05-083', FALSE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "ネリッサ・レイヴンクロフトの杖\nhBP05-083\nネリッサ・レイヴンクロフトの杖\nカードタイプ\nサポート・ツール\nレアリティ\nU\n収録商品\nブースターパック「エンチャントレガリア」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆2nd以上の〈ネリッサ・レイヴンクロフト〉に付いていたら能力追加\n[センターポジション・コラボポジション限定][ターンに1回]このツールが付いているホロメンの能力で自分の手札をアーカイブした時、相手のセンターホロメンかコラボホロメンに特殊ダメージ20を与える。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
