INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP04-089', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "ツートンカラーパソコン\nhBP04-089\nツートンカラーパソコン\nカードタイプ\nサポート・アイテム・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「キュリアスユニバース」 \n能力テキスト\nこのカードは、自分のステージに色が1色で異なる色のホロメンが2人以上いなければ使えない。\n自分のステージの色が1色で異なる色のホロメン2人を選ぶ。自分のデッキから、Buzz以外のそれぞれ選んだホロメンと同色の1stホロメン1枚ずつを公開し、手札に加える。そしてデッキをシャッフルする。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
