INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP04-097', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "緑の試験管\nhBP04-097\n緑の試験管\nカードタイプ\nサポート・ツール\nタグ\n#こよラボ\nレアリティ\nU\n収録商品\nブースターパック「キュリアスユニバース」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆1st以上の〈博衣こより〉に付いていたら能力追加\n自分のメインステップで、このツールが付いているホロメンのエール1枚をアーカイブできる：自分のお休みしている#秘密結社holoXを持つホロメン1人をアクティブにする。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
