INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP04-102', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "やめなー\nhBP04-102\nやめなー\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nブースターパック「キュリアスユニバース」 \n能力テキスト\nこのマスコットが付いているホロメンのアーツ+10。\n◆#5期生を持つ1st以上のホロメンに付いていたら能力追加\n[バックポジション限定]このマスコットが付いているホロメンは相手からダメージを受けない。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
