INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP04-105', FALSE, NULL, NULL, 'REMOVE_CHEER', '{"type": "REMOVE_CHEER", "rawText": "こよりの助手くん\nhBP04-105\nこよりの助手くん\nカードタイプ\nサポート・ファン\nタグ\n#こよラボ\nレアリティ\nU\n収録商品\nブースターパック「キュリアスユニバース」 \n能力テキスト\nこのファンをホロメンに手札かアーカイブから付けた時、自分のステージのエール1枚を、このファンが付いているホロメンに付け替えられる。\nこのファンは、自分の〈博衣こより〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
