INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP03-084', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "ゴージャスパソコン\nhBP03-084\nゴージャスパソコン\nカードタイプ\nサポート・アイテム・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「エリートスパーク」 \n能力テキスト\nこのカードは、自分のホロパワー1枚をアーカイブしなければ使えない。\n自分のデッキから、自分の推しホロメンと同色の1stホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
