INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP03-108', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "はあとん\nhBP03-108\nはあとん\nカードタイプ\nサポート・ファン\nタグ\n#白上''sキャラクター\nレアリティ\nC\n収録商品\nブースターパック「エリートスパーク」 \n能力テキスト\nこのファンが付いているホロメンが能力でサイコロを振った時、このファンをアーカイブできる：そのサイコロの結果をすべて無くし、はじめからサイコロを振り直す。\nこのファンは、自分の〈赤井はあと〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
