INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP03-112', FALSE, NULL, NULL, 'ADD_CHEER', '{"type": "ADD_CHEER", "rawText": "わためいと\nhBP03-112\nわためいと\nカードタイプ\nサポート・ファン\nレアリティ\nU\n収録商品\nブースターパック「エリートスパーク」 \n能力テキスト\n相手のターンで、このファンが付いているホロメンがダウンした時、このホロメンの黄エール1～2枚を、自分の他の〈角巻わため〉1人に付け替えられる。\nこのファンは、自分の〈角巻わため〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
