INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP03-113', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "Risuners\nhBP03-113\nRisuners\nカードタイプ\nサポート・ファン\nレアリティ\nC\n収録商品\nブースターパック「エリートスパーク」 \n能力テキスト\n[ターンに1回]このファンが付いているホロメンにエールが付いた時、このターンの間、このホロメンのアーツ+10。\nこのファンは、自分の〈アユンダ・リス〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
