INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD07-014', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "不知火建設\nhSD07-014\n不知火建設\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nスタートデッキ 黄 不知火フレア \n能力テキスト\nこのカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n自分のデッキの上から4枚を見る。その中から、〈不知火フレア〉と〈尾丸ポルカ〉と〈さくらみこ〉と〈星街すいせい〉と〈白銀ノエル〉を好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
