INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD04-013', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "ちょこのオムライス\nhSD04-013\nちょこのオムライス\nカードタイプ\nサポート・イベント\nタグ\n#食べ物\nレアリティ\nC\n収録商品\nスタートデッキ 紫 癒月ちょこ \n能力テキスト\n自分のホロメン1人を選ぶ。選んだホロメンのHP20回復。自分のステージに#料理を持つホロメンがいる時、さらに、このターンの間、選んだホロメンのアーツ+20。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
