INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD03-013', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "おかにゃん\nhSD03-013\nおかにゃん\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nスタートデッキ 青 猫又おかゆ \n能力テキスト\nこのマスコットが付いているホロメンがセンターポジションかコラボポジションで受けるダメージ-10。\n◆〈猫又おかゆ〉に付いていたら能力追加\nこのマスコットが付いてるホロメンの能力でエールをアーカイブする時、アーカイブする青エール1枚のかわりに、このマスコットをアーカイブできる。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
