INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-079', FALSE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "爆発の魔法\nhBP02-079\n爆発の魔法\nカードタイプ\nサポート・イベント\nタグ\n#魔法\nレアリティ\nU\n収録商品\nブースターパック「クインテットスペクトラム」 \n能力テキスト\n相手のセンターホロメンかコラボホロメンに特殊ダメージ20を与える。ただし、ダウンしても相手のライフは減らない。自分の#魔法を持つイベントはターンに1回しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
