INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-087', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "紫咲シオンの魔法のステッキ\nhBP02-087\n紫咲シオンの魔法のステッキ\nカードタイプ\nサポート・ツール\nタグ\n#魔法\nレアリティ\nC\n収録商品\nブースターパック「クインテットスペクトラム」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆1st以上の〈紫咲シオン〉に付いていたら能力追加\nこのツールが付いているホロメンがセンターホロメンの時、自分の推しスキル「ねえ゛え゛え゛え゛え゛え゛え゛」の[ターンに1回]を[ターンに2回]に変更する。\nツールは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
