INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-102', FALSE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "塩っ子\nhBP02-102\n塩っ子\nカードタイプ\nサポート・ファン\nレアリティ\nC\n収録商品\nブースターパック「クインテットスペクトラム」 \n能力テキスト\n■このファンが付いているホロメンのアーツ+10。\n■このファンが付いているホロメンがダメージを受ける時、このファンをアーカイブする。\nこのファンは、自分の〈紫咲シオン〉だけに付けられ、1人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
