INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-102', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "アイドルマイク\nhBP01-102\nアイドルマイク\nカードタイプ\nサポート・アイテム・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「ブルーミングレディアンス」 \n能力テキスト\nこのカードは、自分の手札がこのカードを含まずに６枚以下でなければ使えない。\n自分のデッキの上から４枚を見る。その中から、#歌を持つホロメンを好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
