INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-110', TRUE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "鈍器でぶっ叩くわよ！\nhBP01-110\n鈍器でぶっ叩くわよ！\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「ブルーミングレディアンス」 \n能力テキスト\nサイコロを１回振る：３以下の時、相手のホロメンのエール１枚をアーカイブする。\n◆自分の推しホロメンが〈七詩ムメイ〉の時、能力変更可能\n[ゲームに１回]相手のセンターホロメンのエール２枚をアーカイブする。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
