INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-115', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "星街すいせいのマイク\nhBP01-115\n星街すいせいのマイク\nカードタイプ\nサポート・ツール\nレアリティ\nU\n収録商品\nブースターパック「ブルーミングレディアンス」 \n能力テキスト\nこのツールが付いているホロメンのアーツ+10。\n◆１st以上の〈星街すいせい〉に付いていたら能力追加\nこのツールが付いているホロメンが相手のホロメンをダウンさせた時、自分のエールデッキの上から１枚を、このホロメンに送る。\nツールは、自分のホロメン１人につき１枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
