INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-117', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "フレンド\nhBP01-117\nフレンド\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nブースターパック「ブルーミングレディアンス」 \n能力テキスト\nこのマスコットが付いているホロメンのアーツ+10。\n◆〈七詩ムメイ〉に付いていたら能力追加\n相手のターンで、このマスコットが付いているホロメンがダメージを受ける時、このマスコットをアーカイブできる：このマスコットが付いていたホロメンが受けるダメージ-30。\nマスコットは、自分のホロメン１人につき１枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
