INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-104', FALSE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "ふつうのパソコン\nhBP01-104\nふつうのパソコン\nカードタイプ\nサポート・アイテム\nレアリティ\nC\n収録商品\nブースターパック「ブルーミングレディアンス」\nスタートデッキ 赤 百鬼あやめ\nスタートデッキ 紫 癒月ちょこ\nスタートデッキ 白 轟はじめ\nスタートデッキ 緑 風真いろは\nスタートデッキ 黄 不知火フレア\nスタートデッキ FLOW GLOW 推し 輪堂千速\nスタートデッキ FLOW GLOW 推し 虎金妃笑虎\nスタートデッキ 推し Advent\nスタートデッキ 推し Justice \n能力テキスト\n自分のデッキから、Debutホロメン１枚を公開し、ステージに出す。そしてデッキをシャッフルする。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
INSERT INTO cards (card_id, name, rarity, image_url, card_type, expansion_code, card_no, tags_json, source_url) VALUES ('HBP01-105', 'ペンライト', 'U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-105_U.png', 'SUPPORT', 'HBP01', 'HBP01-105', '[]'::jsonb, 'https://hololive-official-cardgame.com/cardlist/?id=146&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text') ON CONFLICT (card_id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, image_url = EXCLUDED.image_url, card_type = EXCLUDED.card_type, expansion_code = EXCLUDED.expansion_code, card_no = EXCLUDED.card_no, tags_json = EXCLUDED.tags_json, source_url = EXCLUDED.source_url, updated_at = CURRENT_TIMESTAMP;
INSERT INTO card_variants (card_id, variant_code, variant_name, image_url, source_url, is_default) VALUES ('HBP01-105', 'DEFAULT', '預設圖', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-105_U.png', 'https://hololive-official-cardgame.com/cardlist/?id=146&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text', TRUE) ON CONFLICT (card_id, variant_code) DO UPDATE SET variant_name = EXCLUDED.variant_name, image_url = EXCLUDED.image_url, source_url = EXCLUDED.source_url, is_default = EXCLUDED.is_default, updated_at = CURRENT_TIMESTAMP;
INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-105', TRUE, NULL, NULL, 'REMOVE_CHEER', '{"type": "REMOVE_CHEER", "rawText": "ペンライト\nhBP01-105\nペンライト\nカードタイプ\nサポート・アイテム・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「ブルーミングレディアンス」\nスタートデッキ 青 猫又おかゆ \n能力テキスト\nこのカードは、自分のホロパワー１枚をアーカイブしなければ使えない。\n自分のエールデッキから、自分のホロメン１人と同色のエール１枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
