INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-108', TRUE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "じゃあ敵だね\nhBP01-108\nじゃあ敵だね\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「ブルーミングレディアンス」\nスタートデッキ 赤 百鬼あやめ\nスタートデッキ 青 猫又おかゆ\nスタートデッキ 白 轟はじめ\nスタートデッキ 白 天音かなた\nスタートデッキ 赤 宝鐘マリン\nスタートデッキ 推し Advent \n能力テキスト\n相手のセンターホロメンとバックホロメン１人を交代させる。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'ENEMY_CENTER') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
