INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-114', FALSE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "石の斧\nhBP01-114\n石の斧\nカードタイプ\nサポート・ツール\nレアリティ\nC\n収録商品\nブースターパック「ブルーミングレディアンス」\nブースターパック「エンチャントレガリア」 \n能力テキスト\n■このツールが付いているホロメンのアーツ+20。\n■このツールが付いているホロメンがアーツを使った時、このホロメンに特殊ダメージ10を与える。\n◆１st以上の〈アキ・ローゼンタール〉に付いていたら能力追加\n[ターンに１回]自分の能力で、このホロメンが回復した時、自分のデッキを１枚引く。\nツールは、自分のホロメン１人につき１枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
