INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP01-126', FALSE, NULL, NULL, 'DAMAGE', '{"type": "DAMAGE", "rawText": "座員\nhBP01-126\n座員\nカードタイプ\nサポート・ファン\nレアリティ\nC\n収録商品\nブースターパック「ブルーミングレディアンス」\nブースターパック「エンチャントレガリア」 \n能力テキスト\n■このファンが付いているホロメンがアーツを使う時、このファンを赤エールとしても扱う。\n■このファンが付いているホロメンが受けるダメージ+10。\nこのファンは、自分の〈尾丸ポルカ〉だけに付けられ、１人につき何枚でも付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
