INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-076', FALSE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "カスタムパソコン\nhBP02-076\nカスタムパソコン\nカードタイプ\nサポート・アイテム\nレアリティ\nC\n収録商品\nブースターパック「クインテットスペクトラム」\nスタートデッキ 緑 風真いろは \n能力テキスト\n自分の手札のDebutホロメン1枚を公開し、デッキの下に戻す。自分のデッキから、戻したホロメンと同じカード名のBuzz以外の1stホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
