INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-084', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "みっころね24\nhBP02-084\nみっころね24\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「クインテットスペクトラム」\nスタートデッキ 白 天音かなた\nスタートデッキ 赤 宝鐘マリン \n能力テキスト\n自分のデッキを2枚引き、サイコロを1回振る：3か5か6の時、自分のデッキから、Debutホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。2か4の時、自分のデッキを1枚引く。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
