INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP02-095', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "ドクロくん\nhBP02-095\nドクロくん\nカードタイプ\nサポート・マスコット\nレアリティ\nC\n収録商品\nブースターパック「クインテットスペクトラム」\nスタートデッキ 赤 宝鐘マリン \n能力テキスト\nこのマスコットが付いているホロメンのアーツ+10。\n◆〈宝鐘マリン〉に付いていたら能力追加\n[センターポジション限定]このマスコットが付いているホロメンがBloomした時、自分のデッキを1枚引く。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
