INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HBP03-088', TRUE, NULL, NULL, 'MOVE_ZONE', '{"type": "MOVE_ZONE", "rawText": "凸待ち\nhBP03-088\n凸待ち\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nブースターパック「エリートスパーク」\nスタートデッキ 推し Justice \n能力テキスト\nこのカードは、自分のライフが相手より少ない時にしか使えない。\n相手のコラボホロメンがいない時、相手は、自身のバックホロメン1人をコラボポジションに移動させる（移動はコラボとしては扱わない）。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'BOTH') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
