INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP04-025', '御後がよろしいようで 140+白+50', '自分の推しホロメンが〈儒烏風亭らでん〉の時、このホロメンのエール2枚を、自分のバックホロメン2人に1枚ずつ付け替えられる：このアーツ+30。', '{"GREEN": 2, "COLORLESS": 2}'::jsonb, '{"type": "BUFF", "target": "SELF", "rawHeader": "緑緑◇◇御後がよろしいようで 140+白+50", "rawEffect": "自分の推しホロメンが〈儒烏風亭らでん〉の時、このホロメンのエール2枚を、自分のバックホロメン2人に1枚ずつ付け替えられる：このアーツ+30。"}'::jsonb, 0);
