INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-027', 'ワンフォーオール 130青+50', 'このアーツで相手のホロメンをダウンさせた時、自分のデッキを1枚引く。その後、自分の推しホロメンが〈アキ・ローゼンタール〉なら、自分のホロメン全員のHP20回復。', '{"GREEN": 1, "COLORLESS": 2}'::jsonb, '{"type": "DRAW", "target": "BOTH", "rawHeader": "緑◇◇ワンフォーオール 130青+50", "rawEffect": "このアーツで相手のホロメンをダウンさせた時、自分のデッキを1枚引く。その後、自分の推しホロメンが〈アキ・ローゼンタール〉なら、自分のホロメン全員のHP20回復。"}'::jsonb, 0);
