INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-049', '雨跡をなぞる 60白+50', '相手のバックホロメン全員のHPが合計80以上減っているなら、自分のアーカイブの青エール1枚を自分の〈こぼ・かなえる〉に送れる。', '{"BLUE": 1}'::jsonb, '{"type": "REMOVE_CHEER", "target": "BOTH", "rawHeader": "青雨跡をなぞる 60白+50", "rawEffect": "相手のバックホロメン全員のHPが合計80以上減っているなら、自分のアーカイブの青エール1枚を自分の〈こぼ・かなえる〉に送れる。"}'::jsonb, 0);
INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-049', '残響する雨音 120白+50', 'このホロメンのエール2枚をアーカイブできる：相手のバックホロメン全員に特殊ダメージ30を与える。ただし、ダウンしても相手のライフは減らない。', '{"BLUE": 2, "COLORLESS": 2}'::jsonb, '{"type": "DAMAGE", "target": "ENEMY", "rawHeader": "青青◇◇残響する雨音 120白+50", "rawEffect": "このホロメンのエール2枚をアーカイブできる：相手のバックホロメン全員に特殊ダメージ30を与える。ただし、ダウンしても相手のライフは減らない。"}'::jsonb, 1);
