INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-072', '君と色違いのリュック 50+', '[センターポジション限定]このホロメンにエールが4枚以上付いているなら、このターンの間、このホロメンと自分のコラボホロメンのアーツ+50。', '{"YELLOW": 2}'::jsonb, '{"type": "BUFF", "target": "SELF", "rawHeader": "黄黄君と色違いのリュック 50+", "rawEffect": "[センターポジション限定]このホロメンにエールが4枚以上付いているなら、このターンの間、このホロメンと自分のコラボホロメンのアーツ+50。"}'::jsonb, 0);
INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-072', 'わためと海辺デート 80', '自分の推しホロメンが〈角巻わため〉なら、自分のエールデッキの上から1枚を自分の〈角巻わため〉に送れる。', '{"YELLOW": 2, "COLORLESS": 1}'::jsonb, '{"type": "DAMAGE", "target": "SELF", "rawHeader": "黄黄◇わためと海辺デート 80", "rawEffect": "自分の推しホロメンが〈角巻わため〉なら、自分のエールデッキの上から1枚を自分の〈角巻わため〉に送れる。"}'::jsonb, 1);
