INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP05-073', 'IT''s Time to RE4GE !!!!! 50+白+50', '自分の推しホロメンが〈アユンダ・リス〉なら、自分の#ID1期生を持つホロメン全員のエール1枚につき、このアーツ+10。ただし、数える枚数は10枚まで。', '{"YELLOW": 1, "COLORLESS": 1}'::jsonb, '{"type": "BUFF", "target": "SELF", "rawHeader": "黄◇IT''s Time to RE4GE !!!!! 50+白+50", "rawEffect": "自分の推しホロメンが〈アユンダ・リス〉なら、自分の#ID1期生を持つホロメン全員のエール1枚につき、このアーツ+10。ただし、数える枚数は10枚まで。"}'::jsonb, 0);
