INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP06-060', 'Bull''s-eye!!!! 60赤+50', '自分の推しホロメンが〈森カリオペ〉なら、自分のデッキの上から2枚をアーカイブできる。アーカイブしたなら、自分のエールデッキの上から1枚を自分のホロメンに送る。', '{"COLORLESS": 1}'::jsonb, '{"type": "MOVE_ZONE", "target": "SELF", "rawHeader": "◇Bull''s-eye!!!! 60赤+50", "rawEffect": "自分の推しホロメンが〈森カリオペ〉なら、自分のデッキの上から2枚をアーカイブできる。アーカイブしたなら、自分のエールデッキの上から1枚を自分のホロメンに送る。"}'::jsonb, 0);
INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP06-060', 'Memento Mori. 200+赤+50', 'このターンの間、自分のステージの#Mythを持つホロメン1人のアーツ+20。その後、自分の推しホロメンが〈森カリオペ〉で、自分のアーカイブのホロメンが8枚以上あるなら、自分のデッキを1枚引ける。', '{"COLORLESS": 4}'::jsonb, '{"type": "BUFF", "target": "SELF", "rawHeader": "◇◇◇◇Memento Mori. 200+赤+50", "rawEffect": "このターンの間、自分のステージの#Mythを持つホロメン1人のアーツ+20。その後、自分の推しホロメンが〈森カリオペ〉で、自分のアーカイブのホロメンが8枚以上あるなら、自分のデッキを1枚引ける。"}'::jsonb, 1);
