INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP06-083', 'I am スバル＆わため！ Yeah！！ 80', '[コラボポジション限定]自分の推しホロメンが〈角巻わため〉か〈大空スバル〉なら、このアーツに必要な黄-1。自分のセンターホロメンが2ndホロメンの〈角巻わため〉なら、かわりに、このアーツに必要な黄-3。', '{"YELLOW": 3}'::jsonb, '{"type": "DAMAGE", "target": "SELF_CENTER", "rawHeader": "黄黄黄I am スバル＆わため！ Yeah！！ 80", "rawEffect": "[コラボポジション限定]自分の推しホロメンが〈角巻わため〉か〈大空スバル〉なら、このアーツに必要な黄-1。自分のセンターホロメンが2ndホロメンの〈角巻わため〉なら、かわりに、このアーツに必要な黄-3。"}'::jsonb, 0);
