INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD01-016', TRUE, NULL, NULL, 'DRAW', '{"type": "DRAW", "rawText": "春先のどか\nhSD01-016\n春先のどか\nカードタイプ\nサポート・スタッフ・LIMITED\nレアリティ\nC\n収録商品\nスタートデッキ「ときのそら＆AZKi」\nブースターパック「ブルーミングレディアンス」\nスタートデッキ 赤 百鬼あやめ\nスタートデッキ 青 猫又おかゆ\nスタートデッキ 紫 癒月ちょこ\nスタートデッキ 白 轟はじめ\nスタートデッキ 緑 風真いろは\nスタートデッキ 黄 不知火フレア\nスタートデッキ FLOW GLOW 推し 輪堂千速\nスタートデッキ FLOW GLOW 推し 虎金妃笑虎\nスタートデッキ 推し Advent\nスタートデッキ 推し Justice \n能力テキスト\n自分のデッキを３枚引く。\nLIMITED：ターンに１枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
