INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD01-018', FALSE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "サブパソコン\nhSD01-018\nサブパソコン\nカードタイプ\nサポート・アイテム\nレアリティ\nC\n収録商品\nスタートデッキ「ときのそら＆AZKi」\nスタートデッキ 赤 百鬼あやめ\nスタートデッキ 黄 不知火フレア \n能力テキスト\n自分のデッキの上から５枚を見る。その中から、LIMITEDのサポートカード１枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
