INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD01-019', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "スゴイパソコン\nhSD01-019\nスゴイパソコン\nカードタイプ\nサポート・アイテム・LIMITED\nレアリティ\nC\n収録商品\nスタートデッキ「ときのそら＆AZKi」\nブースターパック「ブルーミングレディアンス」\nスタートデッキ 青 猫又おかゆ\nスタートデッキ 紫 癒月ちょこ\nスタートデッキ FLOW GLOW 推し 虎金妃笑虎\nスタートデッキ 推し Justice \n能力テキスト\nこのカードは、自分のステージのエール1枚をアーカイブしなければ使えない。\n自分のデッキから、Buzz以外の[1stホロメンか2ndホロメン]１枚を公開し、手札に加える。そしてデッキをシャッフルする。\nLIMITED：ターンに1枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
