INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD02-014', FALSE, NULL, NULL, 'BUFF', '{"type": "BUFF", "rawText": "ぽよ余\nhSD02-014\nぽよ余\nカードタイプ\nサポート・マスコット\nタグ\n#白上''sキャラクター\nレアリティ\nC\n収録商品\nスタートデッキ 赤 百鬼あやめ\nブースターパック「アヤカシヴァーミリオン」 \n能力テキスト\nこのマスコットが付いているホロメンのHP+20。\n◆〈百鬼あやめ〉に付いていたら能力追加\nこのマスコットが付いているホロメンがBloomした時、自分のデッキを1枚引く。\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
