INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HSD03-001', 'SP', 'バックショット', '[ホロパワー：1消費][ゲームに1回]自分のステージのホロメンが相手のバックホロメンにダメージを与えた時に使える：その相手のバックホロメン1人に特殊ダメージ50を与える。', 1, '{"type": "DAMAGE", "target": "BOTH", "rawText": "[ホロパワー：1消費][ゲームに1回]自分のステージのホロメンが相手のバックホロメンにダメージを与えた時に使える：その相手のバックホロメン1人に特殊ダメージ50を与える。"}'::jsonb);
