INSERT INTO cards (card_id, name, rarity, image_url, card_type, expansion_code, card_no, tags_json, source_url) VALUES ('HSD10-011', 'WHAT''S UP!!!!! KEEEEEP GROWING!!!!!', 'U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD10/hSD10-011_U.png', 'SUPPORT', 'HSD10', 'HSD10-011', '[]'::jsonb, 'https://hololive-official-cardgame.com/cardlist/?id=1466&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text') ON CONFLICT (card_id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, image_url = EXCLUDED.image_url, card_type = EXCLUDED.card_type, expansion_code = EXCLUDED.expansion_code, card_no = EXCLUDED.card_no, tags_json = EXCLUDED.tags_json, source_url = EXCLUDED.source_url, updated_at = CURRENT_TIMESTAMP;
