INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD10-011', TRUE, NULL, NULL, 'REMOVE_CHEER', '{"type": "REMOVE_CHEER", "rawText": "WHAT''S UP!!!!! KEEEEEP GROWING!!!!!\nhSD10-011\nWHAT''S UP!!!!! KEEEEEP GROWING!!!!!\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nスタートデッキ FLOW GLOW 推し 輪堂千速\nスタートデッキ FLOW GLOW 推し 虎金妃笑虎 \n能力テキスト\nこのカードは、自分のステージのホロメン全員が#FLOW GLOWを持つホロメンでなければ使えない。\n自分のアーカイブのエール3枚を選び、自分のセンターホロメンとコラボホロメンに割り振って送る。ただし、ホロメン1人に送る枚数は2枚まで。\nLIMITED：ターンに1枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF_CENTER') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
INSERT INTO cards (card_id, name, rarity, image_url, card_type, expansion_code, card_no, tags_json, source_url) VALUES ('HSD10-012', 'FLOW GLOW', 'U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD10/hSD10-012_U.png', 'SUPPORT', 'HSD10', 'HSD10-012', '[]'::jsonb, 'https://hololive-official-cardgame.com/cardlist/?id=1467&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text') ON CONFLICT (card_id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, image_url = EXCLUDED.image_url, card_type = EXCLUDED.card_type, expansion_code = EXCLUDED.expansion_code, card_no = EXCLUDED.card_no, tags_json = EXCLUDED.tags_json, source_url = EXCLUDED.source_url, updated_at = CURRENT_TIMESTAMP;
INSERT INTO card_variants (card_id, variant_code, variant_name, image_url, source_url, is_default) VALUES ('HSD10-012', 'DEFAULT', '預設圖', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD10/hSD10-012_U.png', 'https://hololive-official-cardgame.com/cardlist/?id=1467&%2Fcardlist%2Fcardsearch_ex=&expansion=&view=text', TRUE) ON CONFLICT (card_id, variant_code) DO UPDATE SET variant_name = EXCLUDED.variant_name, image_url = EXCLUDED.image_url, source_url = EXCLUDED.source_url, is_default = EXCLUDED.is_default, updated_at = CURRENT_TIMESTAMP;
