INSERT INTO support_cards (card_id, is_limited, condition_type, condition_json, effect_type, effect_json, target_type) VALUES ('HSD10-012', TRUE, NULL, NULL, 'SEARCH', '{"type": "SEARCH", "rawText": "FLOW GLOW\nhSD10-012\nFLOW GLOW\nカードタイプ\nサポート・イベント・LIMITED\nレアリティ\nU\n収録商品\nスタートデッキ FLOW GLOW 推し 輪堂千速\nスタートデッキ FLOW GLOW 推し 虎金妃笑虎 \n能力テキスト\nこのカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n自分のデッキの上から4枚を見る。その中から、#FLOW GLOWを持つホロメンを好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\nLIMITED：ターンに1枚しか使えない。\nMORE", "sections": {}}'::jsonb, 'SELF') ON CONFLICT (card_id) DO UPDATE SET is_limited = EXCLUDED.is_limited, condition_type = EXCLUDED.condition_type, condition_json = EXCLUDED.condition_json, effect_type = EXCLUDED.effect_type, effect_json = EXCLUDED.effect_json, target_type = EXCLUDED.target_type, updated_at = CURRENT_TIMESTAMP;
